INSERT INTO news_posts (news_category_id, author_user_id, post_slug, title, excerpt, content, cover_image_path, post_status, published_at) VALUES
  ((SELECT news_category_id FROM news_categories WHERE category_slug = 'huong-dan'), NULL, 'pc-gaming', 'Hướng dẫn chọn cấu hình PC Gaming phù hợp từng nhu cầu', 'Đặt mục tiêu sử dụng và ngân sách trước, sau đó cân bằng CPU, VGA và khả năng nâng cấp cho bộ máy.', '<p>Khi chọn cấu hình, điều quan trọng là sự cân bằng. CPU xử lý các tác vụ nền và khung hình trong nhiều tựa game, trong khi VGA quyết định phần lớn trải nghiệm ở độ phân giải cao hoặc khi bật thiết lập hình ảnh nặng.</p>
